
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_pbelyp1w_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_pbelyp1w", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.379612622671821e+00, -4.297621092308040e+00, -4.182825443557006e+00, -4.024002351493751e+00, -3.807999393638692e+00, -3.521379348641668e+00, -3.154239186152723e+00, -2.706890754976765e+00, -2.197699478778287e+00, -1.661056699559605e+00, -1.121305413154146e+00, -7.476018395912688e-01, -6.411950575986938e-01, -5.357260459417346e-01, -3.943396147632398e-01, -2.517665468519158e-01, -1.337881092955842e-01, -5.220251010264673e-02, -1.145965533648725e-02, -1.300720300291269e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


